-- CreateIndex (hand-written): one live job per (type, dedupeKey), so the same match run cannot be
-- queued twice; a finished job no longer counts (constitution VIII).
CREATE UNIQUE INDEX "Job_one_live_per_dedupe_key" ON "Job"("type", "dedupeKey")
    WHERE status IN ('QUEUED', 'PROCESSING');

-- CreateIndex (hand-written): one ACTIVE offer per investor per package per round (FR-042); a
-- declined offer no longer counts.
CREATE UNIQUE INDEX "Offer_one_active_per_investor" ON "Offer"("packageId", "investorId", "round")
    WHERE status = 'ACTIVE';

-- AddCheck (hand-written): offer terms are positive or zero, and a financed offer lists the
-- FINANCING contingency.
ALTER TABLE "Offer" ADD CONSTRAINT "Offer_price_check" CHECK ("price" > 0);
ALTER TABLE "Offer" ADD CONSTRAINT "Offer_earnestMoney_check" CHECK ("earnestMoney" >= 0);
ALTER TABLE "Offer" ADD CONSTRAINT "Offer_feesAndConcessions_check" CHECK ("feesAndConcessions" >= 0);
ALTER TABLE "Offer" ADD CONSTRAINT "Offer_financing_check"
    CHECK ("paymentType" <> 'FINANCED' OR 'FINANCING' = ANY ("contingencies"));

-- CreateTrigger (hand-written): offer revisions are history (refuse_append_only_change comes from
-- the publish-fields migration).
CREATE TRIGGER "OfferRevision_append_only" BEFORE UPDATE OR DELETE ON "OfferRevision"
    FOR EACH ROW EXECUTE FUNCTION "refuse_append_only_change"();
